#!/usr/bin/env python3
"""Locate Q4_financial_report.pptx in the workspace and print a compact file listing."""
import os

TARGET = "Q4_financial_report.pptx"
found = []

for root, dirs, files in os.walk("."):
    dirs[:] = [d for d in dirs if not d.startswith(".") and d != "node_modules"]
    for f in files:
        full = os.path.join(root, f)
        if f == TARGET:
            found.append(full)
        print(f"{os.path.getsize(full):>12}  {full}")

print("TARGET_FOUND:", found)

#!/usr/bin/env python3
"""Locate the target pptx file and report candidate paths."""
import os
import sys

target = "Q4_financial_report.pptx"
roots = [os.getcwd(), os.path.expanduser("~"), "/workspace", "/tmp", "/app"]
seen = set()
found = []

for root in roots:
    if not os.path.isdir(root):
        continue
    for dirpath, dirnames, filenames in os.walk(root):
        # Skip noisy directories
        dirnames[:] = [d for d in dirnames if d not in ("node_modules", ".git", ".cache", "site-packages")]
        try:
            for fn in filenames:
                if fn == target:
                    p = os.path.join(dirpath, fn)
                    if p not in seen:
                        seen.add(p)
                        found.append(p)
        except OSError:
            continue

if found:
    for p in found:
        print(p)
    sys.exit(0)
else:
    print("NOT_FOUND")
    # Print a few pptx files as candidates
    for root in roots:
        if not os.path.isdir(root):
            continue
        for dirpath, dirnames, filenames in os.walk(root):
            dirnames[:] = [d for d in dirnames if d not in ("node_modules", ".git", ".cache", "site-packages")]
            try:
                for fn in filenames:
                    if fn.lower().endswith(".pptx"):
                        print("CANDIDATE:", os.path.join(dirpath, fn))
            except OSError:
                continue
    sys.exit(1)

